<script>
  import Icon from './Icon.svelte';
  let {screen}=$props();let m=$derived(screen.model);
  let mode=$derived(m.current===null||m.target===null?'unavailable':m.current-m.target>.5?'cooling':m.current-m.target<-.5?'heating':'holding');
  let angle=$derived((225-((m.target??16)-16)/14*270)*Math.PI/180);
  const guides=Array.from({length:15},(_,i)=>{const a=(225-i/14*270)*Math.PI/180,major=(16+i)%5===0||i===0;return {x1:160+134*Math.cos(a),y1:160-134*Math.sin(a),x2:160+(major?143:139)*Math.cos(a),y2:160-(major?143:139)*Math.sin(a),major};});
</script>
<div class="dial-layout"><button class="temp-side minus" data-action="temp-minus" disabled={m.haMode!=='demo'} aria-label="Lower target by one degree"></button><button class="temp-side plus" data-action="temp-plus" disabled={m.haMode!=='demo'} aria-label="Raise target by one degree"></button>
<div class="thermostat" role="slider" aria-disabled={m.haMode!=='demo'} tabindex={m.haMode==='demo'?0:-1} aria-label="Target temperature" aria-valuemin="16" aria-valuemax="30" aria-valuenow={m.target??undefined} aria-valuetext={`Target ${m.target} degrees Celsius; current ${m.current??'unavailable'}`} data-thermal={mode} style:--dial-offset={100*(1-Math.max(0,Math.min(1,((m.current??16)-16)/14)))}>
<svg viewBox="0 0 320 320" aria-hidden="true"><g class="degree-guides">{#each guides as guide,i (i)}<line x1={guide.x1} y1={guide.y1} x2={guide.x2} y2={guide.y2} class:major={guide.major} />{/each}</g><path class="dial-track" d="M 72.32 247.68 A 124 124 0 1 1 247.68 247.68"/><path class="dial-active" d="M 72.32 247.68 A 124 124 0 1 1 247.68 247.68" pathLength="100"/><text class="dial-limit" x="65" y="272">16</text><text class="dial-limit" x="255" y="272">30</text><g data-dial-pointer style:display={m.target===null?'none':undefined} transform={`translate(${160+124*Math.cos(angle)} ${160-124*Math.sin(angle)})`}><circle class="dial-thumb" r="19"/><text class="target-label" data-target>{m.target}°</text></g></svg><div class="dial-number"><strong data-current-temperature>{m.current??'—'}</strong><span class="temperature-unit"><span class="thermal-mode" data-thermal-mode><Icon name={mode==='cooling'?'snowflake':mode==='heating'?'flame':'minus'} /></span><span>C</span></span></div></div>
<div class="sensor-source"><label for="temperature-source">Display sensor</label><select id="temperature-source" data-input="temperature-sensor" aria-label="Home Assistant temperature sensor" value={m.temperatureSensor} disabled={!m.sensors.length}>{#if !m.sensors.length}<option value="">No temperature sensor configured</option>{/if}{#each m.sensors as sensor (sensor.entity_id)}<option value={sensor.entity_id}>{sensor.attributes.friendly_name} · {screen.temperatureCelsius(sensor)===null?'Unavailable':screen.temperatureCelsius(sensor)+'°C'}</option>{/each}</select><small data-sensor-entity>{m.temperatureSensor||m.haLabel}</small></div></div>
